// const { List } = require("@taf/taf-stream");
var assert = require("assert");

var SeqBuffer = function (pos, data) {
    
    this._pos = pos;
    this._buffer = data;
}

SeqBuffer.prototype.clear = function () {
    this._buffer = Buffer.allocUnsafe(0);
    this._pos = 0;
}

SeqBuffer.prototype.addBuffer = function (data) {
    this._buffer = Buffer.concat([this._buffer, data]);
    this._pos += data.length;
}

SeqBuffer.prototype.assign = function (data) {
    this._buffer = data;
    this._pos = data.length;
}

SeqBuffer.prototype.add = function (ret) {
    this._pos += ret;
    assert(this._pos < this._buffer.length);
}

SeqBuffer.prototype.length = function () {
    return this._buffer.length - this._pos;
}

SeqBuffer.prototype.copy = function (targetBuffer, targetStart) {
    this._buffer.copy(targetBuffer, targetStart, this._pos, this._buffer.length);
}

////////////////////////////////////////////////////////////
var NetworkBuffer = function () {

    this._bufferList = [];
    this._bufferLength = 0;
}

//全局函数，用于创建一个通信器
NetworkBuffer.New = function () {
    return new NetworkBuffer();
};

NetworkBuffer.prototype.getBufferListLength = function () {

    return this._bufferList.length;
}

NetworkBuffer.prototype.addBuffer = function (data) {

    this._bufferList.push(new SeqBuffer(0, data));

    this._bufferLength += data.length;
}

NetworkBuffer.prototype.clear = function () {

    this._bufferList = [];
    this._bufferLength = 0;
}

NetworkBuffer.prototype.getBufferLength = function () {

    return this._bufferLength;
}

//获取长度length的buffer
NetworkBuffer.prototype.getBuffers = function(length) {
    assert(length <= this.getBufferLength());

    var buffer = Buffer.allocUnsafe(length);
    var left = length;
    var pos = 0;

    for (var i = 0; i < this._bufferList.length && left != 0; i++) {
        var len = left;
        if (left > this._bufferList[i].length()) {
            len = this._bufferList[i].length();
        }

        this._bufferList[i].copy(buffer, pos);

        left -= len;
        pos += len;
    }

    assert(buffer.length == length);

    return buffer;
}

//读取头四个字节长度
NetworkBuffer.prototype.readLength = function () {

    return this.getBuffers(4).readUInt32BE(0);

}

NetworkBuffer.prototype.moveHeader = function (len) {

    if (this.getBufferLength() < len)
        return false;

    if (len == 0)
        return true;

    var item = this._bufferList[0];
    assert(item != null);

    var left = item.length();

    if (left > len) {
        item.add(len);
        this._bufferLength -= len;

    } else if (left == len) {
        this._bufferLength -= len;
        this._bufferList.splice(0, 1);
    } else {
        this._bufferLength -= left;
        this._bufferList.splice(0, 1);

        return this.moveHeader(len - left);
    }

    return true;
}

module.exports.NetworkBuffer = NetworkBuffer;